mapper.select:
SELECT COUNT(*)
  FROM CARD_UPLOAD
 WHERE UPLOAD_ID = #{uploadId}
   AND MEMBER_ID = #{memberId}

SELECT e.EXPENSE_ID, e.UPLOAD_ID, e.USED_DATE, e.MERCHANT_NAME, e.PAY_METHOD, e.AMOUNT, c.CATEGORY_CODE, c.CATEGORY_NAME, e.LIST_ID, m.MATCH_TYPE, m.MERCHANT_NAME AS MATCHED_NAME, m.SOURCE_NAME FROM EXPENSE e JOIN SPEND_CATEGORY c ON c.CATEGORY_ID = e.CATEGORY_ID LEFT JOIN MERCHANT_LIST m ON m.LIST_ID = e.LIST_ID WHERE e.MEMBER_ID = #{memberId}
AND e.UPLOAD_ID = #{uploadId}
AND e.USED_DATE >= #{fromDate}
AND e.USED_DATE < #{toDate}
ORDER BY e.USED_DATE DESC, e.EXPENSE_ID DESC

mapper.delete:
DELETE FROM CARD_UPLOAD
 WHERE UPLOAD_ID = #{uploadId}
   AND MEMBER_ID = #{memberId}
